<?php
declare(strict_types=1);require_once __DIR__.'/../includes/task_system_operations.php';
function ops_assert(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
$dir=sys_get_temp_dir().'/dentweb-ops-'.bin2hex(random_bytes(5));mkdir($dir,0700,true);$dbPath=$dir.'/app.sqlite';$db=new PDO('sqlite:'.$dbPath);$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA foreign_keys=ON; CREATE TABLE users(id INTEGER PRIMARY KEY,username TEXT,email TEXT,status TEXT); CREATE TABLE portal_tasks(id INTEGER PRIMARY KEY,assignee_id INTEGER,workflow_status TEXT,proof_required INTEGER,approved_at TEXT,FOREIGN KEY(assignee_id) REFERENCES users(id)); CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,name TEXT,applied_at TEXT);');$db->exec("INSERT INTO users VALUES(1,'safe','safe@example.invalid','active'); INSERT INTO portal_tasks VALUES(1,1,'assigned',0,NULL)");$db=null;
$opened=TaskSystemOperations::open($dbPath);$audit=TaskSystemOperations::audit($opened);ops_assert($audit['summary']['failures']===0,'clean fixture must audit cleanly');ops_assert(TaskSystemOperations::count($opened,'users')===1,'safe count failed');
$backup=$dir.'/backup';mkdir($backup.'/database',0700,true);copy($dbPath,$backup.'/database/app.sqlite');$item=['path'=>'database/app.sqlite','bytes'=>filesize($backup.'/database/app.sqlite'),'sha256'=>hash_file('sha256',$backup.'/database/app.sqlite')];file_put_contents($backup.'/manifest.json',json_encode(['format'=>1,'files'=>[$item]],JSON_THROW_ON_ERROR));ops_assert(TaskSystemOperations::verifyBackup($backup)['valid']===true,'backup verification failed');file_put_contents($backup.'/database/app.sqlite','x',FILE_APPEND);ops_assert(TaskSystemOperations::verifyBackup($backup)['valid']===false,'tampering must fail verification');
$bootstrap=(string)file_get_contents(__DIR__.'/../includes/bootstrap.php');ops_assert(str_contains($bootstrap,"getenv('PORTAL_SEED_DEMO_USERS') === '1'"),'demo seed must require explicit opt-in');ops_assert(str_contains($bootstrap,'Demo seeding is insert-only'),'existing credentials must be preserved');
function ops_rm(string $p):void{if(is_dir($p)){foreach(scandir($p)?:[] as $f)if($f!=='.'&&$f!=='..')ops_rm($p.'/'.$f);rmdir($p);}elseif(is_file($p))unlink($p);}ops_rm($dir);echo "task system operations tests passed\n";
